using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class MetaTests {
  string dir;GameRuntime game;
  [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-meta-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  void ReadyAxiom(){game.Act(s=>{var n=s.Copy();n.Prestige.known=PrestigeBalance.Nodes.Take(30).Select(d=>d.Id).ToArray();n.Prestige.Entitlement=ScientificNumber.From(1e6);return n;});}
  void Lab(bool models=false){game.Act(s=>{var n=s.Copy();n.Prestige.Total=ScientificNumber.From(200000);PrestigeRules.Discover(n);if(models){n.Meta.models[0]=0;n.Meta.models[9]=15;n.Workshop.activeModel="K10";n.Workshop.activeModelLevel=15;n.Workshop.inventory=new[]{new ItemInstance{id="test-a",type="quantum-chip",level=7,rarity=2},new ItemInstance{id="test-b",type="tensor-core",level=3,rarity=3}};n=Workshop.Equip(n,"test-a","universal1");n=Workshop.Equip(n,"test-b","universal2");}return n;});}
  [UnityTest]public IEnumerator AxiomNetworkPreviewSaveAndCancellationDoNotReplayReset(){ReadyAxiom();Click("PrestigeTab");yield return null;Click("NetworkLayer");Assert.That(game.PrestigeView.IsAxiom,Is.True);Assert.That(game.PrestigeView.NodeCount,Is.EqualTo(24));Click("PrestigeReset");Assert.That(GameObject.Find("ResetRetention").GetComponent<Text>().text,Does.Contain("Entfällt"));Assert.That(game.State.Meta.resets,Is.Zero,"Preview has no transaction");Click("ConfirmAxiomReset");Assert.That(game.State.Meta.resets,Is.EqualTo(1));Assert.That(game.PrestigeView.Pulse.IsAnimating,Is.True);var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.State.Meta.resets,Is.EqualTo(1),"Durable before animation");game.PrestigeView.Cancel();game.PrestigeView.OpenNode("A01");Click("BuyINTNode");Assert.That(MetaRules.Level(game.State,"A01"),Is.EqualTo(1));game.PrestigeView.CloseDetail();Click("HardwareTab");yield return null;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Meta.resets,Is.EqualTo(1));Assert.That(MetaRules.Reward(game.State).IsZero,Is.True);}
  [UnityTest]public IEnumerator MiraFirstModelAndReducedRevealAreSavedBeforeTabSwitch(){Lab();Click("ResearchTab");yield return null;Click("SecretLab");yield return null;Assert.That(GameObject.Find("MiraExplanation").GetComponent<Text>().text,Does.Contain("Genau ein Modell"));Click("AcknowledgeMira");yield return null;Click("ModelMotion");yield return null;uint rng=game.State.Meta.rng;Click("DevelopModel");Assert.That(game.State.Meta.models.Count(l=>l>=0),Is.EqualTo(1));Assert.That(game.State.Meta.rng,Is.Not.EqualTo(rng));Assert.That(ScientificNumber.FromData(game.State.Prestige.knowledge).IsZero,Is.True);var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.State.Meta.models,Is.EqualTo(game.State.Meta.models));Assert.That(loaded.State.Meta.tutorial,Is.Empty);Click("HardwareTab");yield return null;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Meta.models.Count(l=>l>=0),Is.EqualTo(1));Assert.That(game.State.Meta.rng,Is.EqualTo(loaded.State.Meta.rng));}
  [UnityTest]public IEnumerator ModelSwitchRemovesOnlyEquipmentBindingsAndPreservesItems(){Lab(true);Click("ResearchTab");yield return null;Click("SecretLab");yield return null;Click("Select-K01");Assert.That(Workshop.ActiveSlots(game.State)[6],Is.False);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(2));Assert.That(game.State.Workshop.inventory[0].level,Is.EqualTo(7));Assert.That(game.State.Workshop.equipped.Skip(6),Is.EqualTo(new[]{"",""}));yield return null;Click("Select-K10");Assert.That(Workshop.ActiveSlots(game.State).Skip(6).All(b=>b),Is.True);Assert.That(game.State.Workshop.equipped.Skip(6).All(string.IsNullOrEmpty),Is.True);}
  [UnityTest]public IEnumerator FundedMobileNetworkLabAndActualReceiptsRender(){ReadyAxiom();Click("PrestigeTab");yield return null;Click("NetworkLayer");var view=game.PrestigeView;view.GetComponentInParent<ScrollRect>().verticalNormalizedPosition=0;yield return null;WorkshopTests.Capture(320,568,"/tmp/unity-axiom-320.png");WorkshopTests.Capture(390,844,"/tmp/unity-axiom-390.png");WorkshopTests.Capture(430,932,"/tmp/unity-axiom-430.png");Click("PrestigeReset");yield return null;WorkshopTests.Capture(320,568,"/tmp/unity-axiom-retention.png");Click("ConfirmAxiomReset");yield return new WaitForSecondsRealtime(.4f);WorkshopTests.Capture(390,844,"/tmp/unity-axiom-pulse.png");view.Cancel();Click("ResearchTab");yield return null;Click("SecretLab");yield return null;WorkshopTests.Capture(390,844,"/tmp/unity-secret-lab.png");WorkshopTests.Capture(320,568,"/tmp/unity-secret-lab-320.png");Click("AcknowledgeMira");yield return null;Click("DevelopModel");yield return new WaitForSecondsRealtime(.4f);WorkshopTests.Capture(390,844,"/tmp/unity-model-reveal.png");}
 }
}
